def ts(seconds_offset: int = 0) -> str:
    """ISO timestamp offset from now, safe against TTL expiry."""
    base = datetime.now(timezone.utc).replace(microsecond=0)
    return (base + timedelta(seconds=seconds_offset)).isoformat()

